package sk.rucki.simple_commit.icons

import com.intellij.openapi.util.IconLoader
import com.intellij.ui.AnimatedIcon
import javax.swing.Icon

/**
 * Animated action icons. The SVG frames are generated by scripts/generate_icons.py,
 * the frame counts here must match the ones it prints.
 */
object SimpleCommitIcons {
    private const val FRAME_DELAY_MS = 100

    val IDLE: Icon = animated("idle", 36)
    val GENERATING: Icon = animated("generating", 12)
    val CREATED: Icon = animated("created", 24)
    val ERROR: Icon = animated("error", 22)

    private fun animated(state: String, frames: Int): Icon =
        AnimatedIcon(FRAME_DELAY_MS, *Array(frames) { load("/icons/$state/${it + 1}.svg") })

    private fun load(path: String): Icon = IconLoader.getIcon(path, SimpleCommitIcons::class.java)
}
